insert into TB_LGCL_ATRB(LGCL_ATRB_SN, LGCL_ENTT_SN, ATRB_NM, ATRB_EXPLN, DATA_TYPE_NM, ESNTL_YN, SORT_ORD, STD_TRM_SN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_LGCL_ATRB, e.LGCL_ENTT_SN, '수정자 아이디', null, null, false, 7, (select STD_TRM_SN from TB_STD_TRM where PRJ_SN = 0 and TRM_NM = '수정자_아이디'), current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_LGCL_ENTT e where e.LGCL_MDL_SN = (select LGCL_MDL_SN from TB_LGCL_MDL where PRJ_SN = 0 and MDL_NM = 'LEXORMA') and e.ENTT_NM = '프로젝트 MCP 설정' and not exists (select 1 from TB_LGCL_ATRB a where a.LGCL_ENTT_SN = e.LGCL_ENTT_SN and a.ATRB_NM = '수정자 아이디');
