insert into TB_TBL(TBL_SN, PRJ_SN, SCHM_SN, TBL_NM, TBL_KORN_NM, TBL_EXPLN, MSTR_TBL_YN, SORT_ORD, APRV_YN, REG_DT, MDFCN_DT, RGTR_ID, MDFR_ID) select next value for SQ_TBL, 0, s.SCHM_SN, 'TB_MCP_TKN', 'MCP 토큰', '프로젝트 범위 MCP 접근 토큰 (DEC-31) : 원문은 발급할 때 한 번만 보이고 해시만 저장한다. 만료 필수, 폐기 가능, 쓸 때마다 발급자의 지금 권한을 다시 확인한다', false, (select coalesce(max(SORT_ORD), 0) + 1 from TB_TBL where PRJ_SN = 0), true, current_timestamp, current_timestamp, 'SYSTEM', 'SYSTEM' from TB_SCHM s where s.PRJ_SN = 0 and s.BSC_YN = true and not exists (select 1 from TB_TBL where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN');
