-- V6 : 선택형 내장 MCP — 프로젝트 MCP 설정·MCP 토큰·MCP 호출 이력 (DEC-31, 2026-11-16 — docs/completed/embedded-mcp-dec31.md).
-- 토큰 원문은 저장하지 않는다 (해시만). 기존 데이터는 바꾸지 않는다 : 설정 행이 없는 프로젝트는 MCP 가 꺼져 있다.
-- 예제(프로젝트 0)에 두 테이블을 용어 → 물리 → 논리 → 매핑 → 관계 → 인덱스 → 업무 설명 순서로 넣는다 (V3~V5 와 같은 규칙).
create sequence SQ_PRJ_MCP_STNG start with 1 increment by 50;
create table TB_PRJ_MCP_STNG (
    PRJ_MCP_STNG_SN bigint not null,
    PRJ_SN bigint not null,
    ACTVTN_YN boolean not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_PRJ_MCP_STNG primary key (PRJ_MCP_STNG_SN)
);
create unique index UX_PRJ_MCP_STNG_01 on TB_PRJ_MCP_STNG (PRJ_SN);
alter table TB_PRJ_MCP_STNG add constraint FK_PRJ_MCP_STNG_01 foreign key (PRJ_SN) references TB_PRJ;
comment on table TB_PRJ_MCP_STNG is '프로젝트 MCP 설정';
comment on column TB_PRJ_MCP_STNG.PRJ_MCP_STNG_SN is '프로젝트 MCP 설정 일련번호';
comment on column TB_PRJ_MCP_STNG.PRJ_SN is '프로젝트 일련번호';
comment on column TB_PRJ_MCP_STNG.ACTVTN_YN is '활성 여부';
comment on column TB_PRJ_MCP_STNG.REG_DT is '등록 일시';
comment on column TB_PRJ_MCP_STNG.MDFCN_DT is '수정 일시';
comment on column TB_PRJ_MCP_STNG.RGTR_ID is '등록자 아이디';
comment on column TB_PRJ_MCP_STNG.MDFR_ID is '수정자 아이디';
create sequence SQ_MCP_TKN start with 1 increment by 50;
create table TB_MCP_TKN (
    MCP_TKN_SN bigint not null,
    PRJ_SN bigint not null,
    ACNT_SN bigint not null,
    TKN_NM varchar(100) not null,
    HASH_VL varchar(255) not null,
    TKN_PFX_NM varchar(20) not null,
    EXPRY_DT timestamp(6) not null,
    DSCD_DT timestamp(6),
    LAST_USE_DT timestamp(6),
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_MCP_TKN primary key (MCP_TKN_SN)
);
create unique index UX_MCP_TKN_01 on TB_MCP_TKN (HASH_VL);
create index IX_MCP_TKN_01 on TB_MCP_TKN (PRJ_SN);
alter table TB_MCP_TKN add constraint FK_MCP_TKN_01 foreign key (PRJ_SN) references TB_PRJ;
comment on table TB_MCP_TKN is 'MCP 토큰';
comment on column TB_MCP_TKN.MCP_TKN_SN is 'MCP 토큰 일련번호';
comment on column TB_MCP_TKN.PRJ_SN is '프로젝트 일련번호';
comment on column TB_MCP_TKN.ACNT_SN is '계정 일련번호';
comment on column TB_MCP_TKN.TKN_NM is '토큰 명';
comment on column TB_MCP_TKN.HASH_VL is '해시 값';
comment on column TB_MCP_TKN.TKN_PFX_NM is '토큰 접두어 명';
comment on column TB_MCP_TKN.EXPRY_DT is '만료 일시';
comment on column TB_MCP_TKN.DSCD_DT is '폐기 일시';
comment on column TB_MCP_TKN.LAST_USE_DT is '최종 사용 일시';
comment on column TB_MCP_TKN.REG_DT is '등록 일시';
comment on column TB_MCP_TKN.MDFCN_DT is '수정 일시';
comment on column TB_MCP_TKN.RGTR_ID is '등록자 아이디';
comment on column TB_MCP_TKN.MDFR_ID is '수정자 아이디';
create sequence SQ_MCP_CALL_HSTRY start with 1 increment by 50;
create table TB_MCP_CALL_HSTRY (
    MCP_CALL_HSTRY_SN bigint not null,
    PRJ_SN bigint not null,
    MCP_TKN_SN bigint not null,
    TOOL_NM varchar(100) not null,
    RSLT_CD varchar(20) not null,
    CALL_DT timestamp(6) not null,
    REG_DT timestamp(6),
    MDFCN_DT timestamp(6),
    RGTR_ID varchar(255),
    MDFR_ID varchar(255),
    constraint PK_MCP_CALL_HSTRY primary key (MCP_CALL_HSTRY_SN)
);
create index IX_MCP_CALL_HSTRY_01 on TB_MCP_CALL_HSTRY (MCP_TKN_SN);
create index IX_MCP_CALL_HSTRY_02 on TB_MCP_CALL_HSTRY (PRJ_SN);
comment on table TB_MCP_CALL_HSTRY is 'MCP 호출 이력';
comment on column TB_MCP_CALL_HSTRY.MCP_CALL_HSTRY_SN is 'MCP 호출 이력 일련번호';
comment on column TB_MCP_CALL_HSTRY.PRJ_SN is '프로젝트 일련번호';
comment on column TB_MCP_CALL_HSTRY.MCP_TKN_SN is 'MCP 토큰 일련번호';
comment on column TB_MCP_CALL_HSTRY.TOOL_NM is '도구 명';
comment on column TB_MCP_CALL_HSTRY.RSLT_CD is '결과 코드';
comment on column TB_MCP_CALL_HSTRY.CALL_DT is '호출 일시';
comment on column TB_MCP_CALL_HSTRY.REG_DT is '등록 일시';
comment on column TB_MCP_CALL_HSTRY.MDFCN_DT is '수정 일시';
comment on column TB_MCP_CALL_HSTRY.RGTR_ID is '등록자 아이디';
comment on column TB_MCP_CALL_HSTRY.MDFR_ID is '수정자 아이디';

-- ---------- 예제 : 데이터 사전 (새 단어·새 용어) ----------
-- ---------- 예제 : 물리 모델 TB_PRJ_MCP_STNG ----------
-- ---------- 예제 : 논리 모델 프로젝트 MCP 설정 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 프로젝트 MCP 설정 ----------
-- ---------- 예제 : 관계 TB_PRJ_MCP_STNG (V6 의 FK 그대로, 삭제 규칙 포함) ----------
-- ---------- 예제 : 인덱스 TB_PRJ_MCP_STNG (V6 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 TB_PRJ_MCP_STNG ----------
update TB_TBL set TASK_EXPLN = '프로젝트 관리자가 외부 MCP 클라이언트의 읽기 전용 메타데이터 조회를 허용했는지 기록한다. 행이 없으면 꺼져 있다.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = 'MCP 설정 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'PRJ_MCP_STNG_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '설정이 속한 프로젝트 (프로젝트마다 한 행).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '이 프로젝트를 MCP 로 조회할 수 있는지 여부.' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'ACTVTN_YN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_PRJ_MCP_STNG' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
-- ---------- 예제 : 물리 모델 TB_MCP_TKN ----------
-- ---------- 예제 : 논리 모델 MCP 토큰 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 MCP 토큰 ----------
-- ---------- 예제 : 관계 TB_MCP_TKN (V6 의 FK 그대로, 삭제 규칙 포함) ----------
-- ---------- 예제 : 인덱스 TB_MCP_TKN (V6 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 TB_MCP_TKN ----------
update TB_TBL set TASK_EXPLN = '외부 MCP 클라이언트가 한 프로젝트의 메타데이터를 읽기 전용으로 조회할 때 쓰는 토큰. 토큰 자체에 권한을 고정하지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'MCP_TKN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰으로 조회할 수 있는 프로젝트 (하나뿐).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰을 발급한 계정. 쓸 때마다 이 계정의 지금 상태·멤버십·역할을 확인한다.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'ACNT_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰을 구분하는 이름 (용도).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'TKN_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰 원문의 SHA-256 해시. 원문은 저장하지 않는다.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'HASH_VL' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '목록에서 토큰을 알아보도록 남기는 앞부분 (인증에 쓰지 않는다).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'TKN_PFX_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰을 더 쓸 수 없게 되는 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'EXPRY_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰을 폐기한 일시. 있으면 쓸 수 없다.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'DSCD_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '토큰으로 마지막으로 조회한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'LAST_USE_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_TKN' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
-- ---------- 예제 : 물리 모델 TB_MCP_CALL_HSTRY ----------
-- ---------- 예제 : 논리 모델 MCP 호출 이력 ----------
-- ---------- 예제 : 논리 ↔ 물리 매핑 MCP 호출 이력 ----------
-- ---------- 예제 : 인덱스 TB_MCP_CALL_HSTRY (V6 의 create index 그대로) ----------
-- ---------- 예제 : 업무 설명 TB_MCP_CALL_HSTRY ----------
update TB_TBL set TASK_EXPLN = '어떤 토큰으로 언제 어떤 MCP 도구를 불렀고 결과가 어땠는지 남긴 기록.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '호출 이력 행을 구분하는 내부 번호.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'MCP_CALL_HSTRY_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '호출한 프로젝트.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'PRJ_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '호출에 쓴 토큰 (번호로만 남는다).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'MCP_TKN_SN' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '부른 도구 또는 MCP 메서드 이름.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'TOOL_NM' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '호출 결과 : 성공·거절·오류.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'RSLT_CD' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '호출한 일시.' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'CALL_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'REG_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 일시 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'MDFCN_DT' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 등록한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'RGTR_ID' and TASK_EXPLN is null;
update TB_COL set TASK_EXPLN = '행을 마지막으로 수정한 사용자 (감사).' where PRJ_SN = 0 and TBL_NM = 'TB_MCP_CALL_HSTRY' and COL_NM = 'MDFR_ID' and TASK_EXPLN is null;
